INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36011, 'Luke 16:27', 'Luke', 16, 27, 'هغه شتمن سړي وویل: ‹ای زما پلاره ابراهیمه! زه تاته زارۍ کوم چې ایلعازر زما د پلار کور ته ولېږه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_27.mp3', '', 1761754199, 1761754199),
(36012, 'Luke 16:28', 'Luke', 16, 28, 'ځکه چې زه پنځه ورونه لرم. پرېږده چې هغه لاړ شي او هغوی خبر کړي، هسې نه چې هغوی هم دې د عذاب ځای ته راشي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_28.mp3', '', 1761754199, 1761754199),
(36013, 'Luke 16:29', 'Luke', 16, 29, 'ابراهیم وویل: ‹د هغوی سره د موسی او نورو پیغمبرانو لیکنې شته، نو باید د هغوی خبرو ته غوږ ونیسي او عمل پرې وکړي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_29.mp3', '', 1761754199, 1761754199),
(36014, 'Luke 16:30', 'Luke', 16, 30, 'شتمن سړي ځواب ورکړ: ‹نه، ای زما نیکه ابراهیمه! خو که له مړو څخه څوک هغوی ته ورشي، نو هغوی به توبه وباسي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_30.mp3', '', 1761754199, 1761754199),
(36015, 'Luke 16:31', 'Luke', 16, 31, 'خو ابراهیم ورته وویل: ‹که چېرې هغوی د موسی او نورو پیغمبرانو خبرو ته غوږ ونه نیسي، نو که د مړو څخه هم څوک راپاڅیږي، هغوی به قانع نه شي.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_31.mp3', '', 1761754199, 1761754199),
(36016, 'Luke 9:1', 'Luke', 9, 1, 'عیسی خپل دولس رسولان راوغوښتل او هغوی ته یې قدرت او اختیار ورکړ چې پېریان وباسي او د ناروغیو علاج وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_1.mp3', '', 1761754199, 1761754199),
(36017, 'Luke 9:2', 'Luke', 9, 2, 'نو هغوی یې ولېږل چې د خدای پاچاهي اعلان کړي او ناروغان روغ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_2.mp3', '', 1761754199, 1761754199),
(36018, 'Luke 9:3', 'Luke', 9, 3, 'هغوی ته یې وویل: «د سفر دپاره د ځان سره هېڅ شی مه اخلئ. نه امسا، نه خورجین، نه ډوډۍ، نه پیسې او نه اضافي کالي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_3.mp3', '', 1761754199, 1761754199),
(36019, 'Luke 9:4', 'Luke', 9, 4, 'کله چې تاسو کوم کور ته ورشئ، نو ترڅو پورې چې په هغه ښار کې یئ په هماغه کور کې پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_4.mp3', '', 1761754199, 1761754199),
(36020, 'Luke 9:5', 'Luke', 9, 5, 'که چېرې تاسو ته په کوم ځای کې څوک هرکلی ونه وایي، نو هغه ښار پرېږدئ او د هغه ښار خاورې د خپلو پښو څخه وڅنډئ، ترڅو د هغوی په خلاف شاهدي وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_5.mp3', '', 1761754199, 1761754199),
(36021, 'Luke 9:6', 'Luke', 9, 6, 'نو هغوی روان شول، کلي په کلي ګرځېدل او په هرځای کې یې زېری ورکاوه او خلک یې روغول. د هیرودیس پرېشاني (متي ۱۴‏:‌۱‌‏-‌۱۲ او مرقوس ۶‏:‌۱۴‌‏-‌۲۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_6.mp3', '', 1761754199, 1761754199),
(36022, 'Luke 9:7', 'Luke', 9, 7, 'کله چې د جلیل والي هیرودیس د هغو ټولو کارونو څخه چې وشول خبر شو نو ډېر پرېشانه شو، ځکه چې ځینو خلکو به ویل چې یحیی بېرته راژوندی شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_7.mp3', '', 1761754199, 1761754199),
(36023, 'Luke 9:8', 'Luke', 9, 8, 'نورو به ویل چې الیاس پیغمبر راښکاره شوی دی او ځینو به ویل چې د پخوانیو پیغمبرانو څخه کوم یو راژوندی شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_8.mp3', '', 1761754199, 1761754199),
(36024, 'Luke 9:9', 'Luke', 9, 9, 'خو هیرودیس وویل: «ما په خپله د یحیی سر پرې کړی دی، نو بیا دا سړی څوک دی چې په هکله یې داسې شیان اورم؟» هیرودیس کوښښ کاوه چې عیسی وویني. پنځو زرو کسانو ته خواړه ورکول (متي ۱۴‏:‌۱۳‌‏-‌۲۱ او مرقوس ۶‏:‌۳۰‌‏-‌۴۴ او یوحنا ۶‏:‌۱‌‏-‌۱۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_9.mp3', '', 1761754199, 1761754199),
(36025, 'Luke 9:10', 'Luke', 9, 10, 'کله چې رسولان بېرته راغلل، نو کوم کارونه چې هغوی کړي وو هغه یې عیسی ته بیان کړل. عیسی هغوی د ځان سره واخیستل او د بیت‌صیدا په نوم ښار ته یوازې لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_10.mp3', '', 1761754199, 1761754199),
(36026, 'Luke 9:11', 'Luke', 9, 11, 'خو خلک خبر شول او ورپسې لاړل. عیسی هغوی ته هرکلی ووایه، د هغوی سره یې د خدای د پاچاهۍ په هکله خبرې وکړې او هغو خلکو ته یې شفا ورکړه چې روغتیا ته یې اړتیا درلودله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_11.mp3', '', 1761754199, 1761754199),
(36027, 'Luke 9:12', 'Luke', 9, 12, 'کله چې مازدیګر شو، نو هغه دولس شاګردان عیسی ته راغلل او ورته ویې ویل: «دا خلک رخصت کړه چې کلیو او شاوخوا بانډو ته لاړ شي چې ځانونو ته خواړه او د شپې تېرولو دپاره ځای پیدا کړي. دلته هېڅ شی نشته او دا ځای د دښتې په شان دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_12.mp3', '', 1761754199, 1761754199),
(36028, 'Luke 9:13', 'Luke', 9, 13, 'خو عیسی هغوی ته وویل: «تاسو خپله هغوی ته څه ورکړئ چې ویې خوري.» هغوی وویل: «مونږ سره یوازې پنځه ډوډۍ او دوه ماهیان دي، نور هېڅ هم نشته. ایا تاسو غواړئ چې مونږ خپله لاړ شو او دې ټولو خلکو ته خواړه واخلو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_13.mp3', '', 1761754199, 1761754199),
(36029, 'Luke 9:14', 'Luke', 9, 14, '(هلته شاوخوا پنځه زره سړي وو.) عیسی خپلو شاګردانو ته وویل: «هغوی پنځوس پنځوس تنه کښېنوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_14.mp3', '', 1761754199, 1761754199),
(36030, 'Luke 9:15', 'Luke', 9, 15, 'شاګردانو همداسې وکړل او ټول یې کښېنول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_15.mp3', '', 1761754199, 1761754199),
(36031, 'Luke 9:16', 'Luke', 9, 16, 'عیسی هغه پنځه ډوډۍ او دوه ماهیان راواخیستل، پورته اسمان ته یې وکتل او د خدای شکر یې وویست. بیا هغه ډوډۍ ماتې کړې او خپلو شاګردانو ته یې ورکړې چې د خلکو په مخکې یې کېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_16.mp3', '', 1761754199, 1761754199),
(36032, 'Luke 9:17', 'Luke', 9, 17, 'هغوی ټولو وخوړل او ماړه شول او د ډوډۍ کومې ټوټې چې پاتې شوې شاګردانو هغه راټولې کړې او د هغو څخه دولس ټوکرۍ ډکې شوې. د عیسی په هکله د پطروس اقرار (متي ۱۶‏:‌۱۳‌‏-‌۱۹ او مرقوس ۸‏:‌۲۷‌‏-‌۲۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_17.mp3', '', 1761754199, 1761754199),
(36033, 'Luke 9:18', 'Luke', 9, 18, 'یوه ورځ چې عیسی په یو ګوښه ځای کې دعا کوله او شاګردان یې هم هلته وو، د هغوی څخه یې پوښتنه وکړه: «خلک څه وایي چې زه څوک یم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_18.mp3', '', 1761754199, 1761754199),
(36034, 'Luke 9:19', 'Luke', 9, 19, 'هغوی په ځواب کې وویل: «ځینې وایي چې ته تعمید ورکوونکی یحیی یې، ځینې وایي چې الیاس نبي یې، او نور وایي چې د پخوانیو پیغمبرانو څخه کوم یو راژوندی شوی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_19.mp3', '', 1761754199, 1761754199),
(36035, 'Luke 9:20', 'Luke', 9, 20, 'نو عیسی د هغوی څخه پوښتنه وکړه: «تاسو څه وایئ چې زه څوک یم؟» پطروس په ځواب کې وویل: «ته د خدای مسیح یې.» عیسی د خپل مرګ په هکله پېشګويي کوي (متي ۱۶‏:‌۲۰‌‏-‌۲۸ او مرقوس ۸‏:‌۳۰‌‏-‌۳۸، ۹‏:‌۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_20.mp3', '', 1761754199, 1761754199),
(36036, 'Luke 9:21', 'Luke', 9, 21, 'بیا عیسی هغوی ته په کلکه حکم وکړ چې په دې هکله چاته څه ونه وایي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_21.mp3', '', 1761754199, 1761754199),
(36037, 'Luke 9:22', 'Luke', 9, 22, 'او ویې ویل: «دا ضروري ده چې د انسان زوی به ډېر کړاوونه وزغمي او د قوم د مشرانو، مشرانو کاهنانو او د شریعت د عالمانو له خوا به رد کړای شي. هغه به ووژل شي او په درېمه ورځ به بیا راژوندی شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_22.mp3', '', 1761754199, 1761754199),
(36038, 'Luke 9:23', 'Luke', 9, 23, 'بیا یې هغوی ټولو ته وویل: «که څوک غواړي چې زما د پیروانو څخه اوسي نو باید د خپل ځان څخه تېر شي، هره ورځ دې خپل صلیب را‌واخلي او په ما پسې دې راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_23.mp3', '', 1761754199, 1761754199),
(36039, 'Luke 9:24', 'Luke', 9, 24, 'ځکه څوک چې غواړي خپل ژوند وساتي هغه به له لاسه ورکړي، خو څوک چې خپل ژوند زما په خاطر له لاسه ورکوي نو وبه یې ساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_24.mp3', '', 1761754199, 1761754199),
(36040, 'Luke 9:25', 'Luke', 9, 25, 'د یو چا دپاره به په دې کې څه ګټه وي چې ټوله نړۍ وګټي، خو خپل ځان له لاسه ورکړي یا هغه ته زیان ورسوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_25.mp3', '', 1761754199, 1761754199),
(36041, 'Luke 9:26', 'Luke', 9, 26, 'که چېرې څوک په ما او یا زما په تعلیم شرمیږي، نو د انسان زوی به هم کله چې د خپل جلال او د پلار او سپېڅلو فرښتو د جلال سره راشي، په هغه وشرمیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_26.mp3', '', 1761754199, 1761754199),
(36042, 'Luke 9:27', 'Luke', 9, 27, 'زه تاسو ته رښتیا وایم چې دلته ځینې داسې خلک ولاړ دي چې تر هغې پورې به مړه نه شي، ترڅو یې د خدای پاچاهي نه وي لیدلې.» د عیسی د څېرې بدلېدل (متي ۱۷‏:‌۱‌‏-‌۸ او مرقوس ۹‏:‌۲‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_27.mp3', '', 1761754199, 1761754199),
(36043, 'Luke 9:28', 'Luke', 9, 28, 'د دې خبرو څخه شاوخوا اته ورځې وروسته عیسی پطروس، یوحنا او یعقوب د ځان سره واخیستل او د دعا دپاره یو غره ته وختل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_28.mp3', '', 1761754199, 1761754199),
(36044, 'Luke 9:29', 'Luke', 9, 29, 'کله چې عیسی دعا کوله، نو څېره یې بدله شوه او کالي یې سپین وځلېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_29.mp3', '', 1761754199, 1761754199),
(36045, 'Luke 9:30', 'Luke', 9, 30, 'ناڅاپه هلته دوه سړي راښکاره شول چې د عیسی سره یې خبرې کولې او هغوی موسی او الیاس وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_30.mp3', '', 1761754199, 1761754199),
(36046, 'Luke 9:31', 'Luke', 9, 31, 'هغوی په اسماني جلال کې راښکاره شول او د عیسی سره یې د خدای د هغه مقصد په هکله چې د هغه په مرګ به په اورشلیم کې پوره شي، خبرې وکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_31.mp3', '', 1761754199, 1761754199),
(36047, 'Luke 9:32', 'Luke', 9, 32, 'په دې وخت کې پطروس او د هغه ملګري په درانه خوب ویده شوي وو، خو کله چې راویښ شول، نو د عیسی جلال او هغه دوه سړي چې ورسره ولاړ وو، ولیدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_32.mp3', '', 1761754199, 1761754199),
(36048, 'Luke 9:33', 'Luke', 9, 33, 'کله چې موسی او الیاس له عیسی څخه تلل، نو پطروس عیسی ته وویل: «استاذه! څومره ښه ده چې مونږ دلته یو. راځئ چې درې خېمې جوړې کړو، یوه تاته، یوه موسی ته او یوه الیاس ته.» خو پطروس نه پوهېده چې څه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_33.mp3', '', 1761754199, 1761754199),
(36049, 'Luke 9:34', 'Luke', 9, 34, 'هغه لا خبرې کولې چې یوه ورېځ راښکاره شوه او په هغوی باندې یې سیوری وکړ. کله چې شاګردان په ورېځو کې را‌ایسار شول، نو ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_34.mp3', '', 1761754199, 1761754199),
(36050, 'Luke 9:35', 'Luke', 9, 35, 'د ورېځې څخه یو اواز راغی او ویل یې: «دا زما زوی دی چې ما غوره کړی دی، هغه ته غوږ ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_35.mp3', '', 1761754199, 1761754199),
(36051, 'Luke 9:36', 'Luke', 9, 36, 'کله چې اواز غلی شو، هغوی ولیدل چې عیسی هلته یوازې ؤ. شاګردان غلي پاتې شول او څه چې یې لیدلي وو په هغه وخت کې یې د هغو په هکله چاته څه ونه ویل. عیسی د یو هلک څخه پېریان وباسي (متي ۱۷‏:‌۱۴‌‏-‌۱۸ او مرقوس ۹‏:‌۱۴‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_36.mp3', '', 1761754199, 1761754199),
(36052, 'Luke 9:37', 'Luke', 9, 37, 'بله ورځ کله چې عیسی د خپلو درېو شاګردانو سره د غره څخه راښکته شو، نو ډېر خلک راغلل چې د هغه سره وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_37.mp3', '', 1761754199, 1761754199),
(36053, 'Luke 9:38', 'Luke', 9, 38, 'ناڅاپه د هغې ډلې څخه یو سړي چیغه کړه: «ای استاذه! زه درته زاري کوم چې زما زوی ته یو نظر وګوره، هغه زما یوازېنی زوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_38.mp3', '', 1761754199, 1761754199),
(36054, 'Luke 9:39', 'Luke', 9, 39, 'په هغه باندې پېریان راځي او ناڅاپه چیغې ورڅخه وباسي او داسې ټکانونه ورکوي چې د خولې څخه یې ځګونه روان وي. له ډېرو ځپلو وروسته یې په سختۍ سره پرېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_39.mp3', '', 1761754199, 1761754199),
(36055, 'Luke 9:40', 'Luke', 9, 40, 'ستا شاګردانو ته مې زارۍ وکړې چې پېریان ترې وباسي، خو هغوی ونه شو کولای.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_40.mp3', '', 1761754199, 1761754199),
(36056, 'Luke 9:41', 'Luke', 9, 41, 'عیسی په ځواب کې وویل: «ای د دې زمانې بې‌ایمانه او بې‌لارې خلکو! ترڅو پورې به زه ستاسو سره یم او ترڅو پورې به تاسو ته حوصله کوم؟» بیا یې هغه سړي ته وویل: «زوی دې دلته راوله.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_41.mp3', '', 1761754199, 1761754199),
(36057, 'Luke 9:42', 'Luke', 9, 42, 'هلک لا راروان ؤ چې پېریانو هغه په ځمکه راګوزار کړ او ویې لړزاوه. عیسی پېریانو ته حکم وکړ چې ترې ووځي او هغه هلک یې روغ کړ او هغه یې بېرته خپل پلار ته وسپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_42.mp3', '', 1761754199, 1761754199),
(36058, 'Luke 9:43', 'Luke', 9, 43, 'ټول خلک د خدای لویۍ ته حیران پاتې شول. عیسی د دوهم ځل دپاره د خپل مرګ په هکله پېشګويي کوي (متي ۱۷‏:‌۲۲‌‏-‌۲۳ او مرقوس ۹‏:‌۳۰‌‏-‌۳۲) په داسې حال کې چې ټول خلک د عیسی دې کارونو ته حیران پاتې وو هغه خپلو شاګردانو ته وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_43.mp3', '', 1761754199, 1761754199),
(36059, 'Luke 9:44', 'Luke', 9, 44, '«زه چې تاسو ته څه وایم هغه ته په غور سره غوږ ونیسئ: د انسان زوی به خپلو دښمنانو ته په لاس ورکړل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_44.mp3', '', 1761754199, 1761754199),
(36060, 'Luke 9:45', 'Luke', 9, 45, 'خو شاګردان په دې پوه نه شول چې د دې خبرې معنی څه ده. د دې معنی د هغوی څخه پټه ساتل شوې وه چې ورباندې پوه نه شي او هغوی وېرېدل چې په دې هکله د هغه څخه پوښتنه وکړي. د ټولو نه لوی څوک دی؟ (متي ۱۸‏:‌۱‌‏-‌۵ او مرقوس ۹‏:‌۳۳‌‏-‌۳۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_45.mp3', '', 1761754199, 1761754199),
(36061, 'Luke 9:46', 'Luke', 9, 46, 'بیا د شاګردانو ترمنځ دا بحث پیل شو چې په دوی کې څوک تر ټولو لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_46.mp3', '', 1761754199, 1761754199),
(36062, 'Luke 9:47', 'Luke', 9, 47, 'عیسی پوه شو چې د هغوی په زړونو کې څه ګرځي، نو هغه یو ماشوم راوست او په خپل څنګ کې یې ودراوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_47.mp3', '', 1761754199, 1761754199),
(36063, 'Luke 9:48', 'Luke', 9, 48, 'او هغوی ته یې وویل: «هرڅوک چې دا ماشوم زما په نوم قبول کړي، نو زه یې قبول کړی یم او څوک چې ما قبول کړي، نو هغه څوک یې قبول کړی دی چې زه یې رالېږلی یم. ځکه چې په تاسو ټولو کې تر ټولو کوچنی تر ټولو لوی دی.» څوک چې ستاسو مخالف نه دی هغه ستاسو طرفدار دی (مرقوس ۹‏:‌۳۸‌‏-‌۴۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_48.mp3', '', 1761754199, 1761754199),
(36064, 'Luke 9:49', 'Luke', 9, 49, 'یوحنا عیسی ته وویل: «استاذه! مونږ یو سړی ولیده چې ستا په نوم یې پېریان ویستل خو مونږ هغه د دې کار څخه منع کړ، ځکه چې هغه زمونږ د ډلې څخه نه ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_49.mp3', '', 1761754199, 1761754199),
(36065, 'Luke 9:50', 'Luke', 9, 50, 'عیسی هغه ته وویل: «هغه مه منع کوئ، ځکه څوک چې ستاسو مخالف نه دی هغه ستاسو طرفدار دی.» د سامرې د یو کلي خلک د عیسی د منلو څخه انکار کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_50.mp3', '', 1761754199, 1761754199),
(36066, 'Luke 9:51', 'Luke', 9, 51, 'کله چې هغه وخت رانژدې شو چې عیسی اسمان ته یووړل شي، نو په ټینګې ارادې سره اورشلیم ته روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_51.mp3', '', 1761754199, 1761754199),
(36067, 'Luke 9:52', 'Luke', 9, 52, 'هغه د ځان څخه مخکې استازي ولېږل. هغوی لاړل او د سامرې یو کلي ته ورغلل چې د هغه دپاره تیاری ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_52.mp3', '', 1761754199, 1761754199),
(36068, 'Luke 9:53', 'Luke', 9, 53, 'خو د هغه کلي خلکو عیسی قبول نه کړ، ځکه چې دا ښکاره وه چې هغه د اورشلیم خواته روان ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_53.mp3', '', 1761754199, 1761754199),
(36069, 'Luke 9:54', 'Luke', 9, 54, 'کله چې د هغه شاګردانو یعقوب او یوحنا دا ولیدل، نو هغوی وویل: «استاذه! ایا ته زمونږ څخه غواړې چې ووایو د اسمان څخه دې اور رانازل شي او دا خلک وسوځوي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_54.mp3', '', 1761754199, 1761754199),
(36070, 'Luke 9:55', 'Luke', 9, 55, 'خو عیسی ورته مخ راواړاوه او هغوی یې ورټل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_55.mp3', '', 1761754199, 1761754199),
(36071, 'Luke 9:56', 'Luke', 9, 56, 'بیا هغوی بل کلي ته لاړل. د عیسی څخه د پیروۍ کولو شرطونه (متي ۸‏:‌۱۹‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_56.mp3', '', 1761754199, 1761754199),
(36072, 'Luke 9:57', 'Luke', 9, 57, 'کله چې هغوی په لاره روان وو، یو سړي عیسی ته وویل: «هر‌چېرته چې ځې زه به درپسې ځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_57.mp3', '', 1761754199, 1761754199),
(36073, 'Luke 9:58', 'Luke', 9, 58, 'عیسی هغه ته وویل: «ګیدړان خپل غارونه لري او مرغان ځالې، خو د انسان زوی دومره ځای هم نه لري چې خپل سر ورباندې کېږدي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_58.mp3', '', 1761754199, 1761754199),
(36074, 'Luke 9:59', 'Luke', 9, 59, 'عیسی یو بل سړي ته وویل: «ما پسې راځه.» خو هغه سړي وویل: «ښاغلیه! اجازه راکړه چې لومړی لاړ شم او خپل پلار خاورو ته وسپارم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_59.mp3', '', 1761754199, 1761754199),
(36075, 'Luke 9:60', 'Luke', 9, 60, 'عیسی هغه ته وویل: «پرېږده چې مړي خپل مړي ښخ کړي. ته لاړ شه او د خدای د پاچاهۍ اعلان وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_60.mp3', '', 1761754199, 1761754199),
