(36077, 'Luke 9:62', 'Luke', 9, 62, 'عیسی هغه ته وویل: «څوک چې د قلبې کولو په وخت کې شاته ګوري، هغه د خدای د پاچاهۍ وړ نه دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke9_verse_62.mp3', '', 1761754199, 1761754199),
(36078, 'Luke 21:1', 'Luke', 21, 1, 'عیسی شاوخوا وکتل او ویې لیدل چې شتمن خلک خپلې نذرانې د خدای د کور په خزانه کې اچوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_1.mp3', '', 1761754199, 1761754199),
(36079, 'Luke 21:2', 'Luke', 21, 2, 'او همدارنګه هغه یوه غریبه کونډه ولیدله چې خپلې دوه روپۍ یې په هغې خزانه کې واچولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_2.mp3', '', 1761754199, 1761754199),
(36080, 'Luke 21:3', 'Luke', 21, 3, 'عیسی وویل: «زه تاسو ته رښتیا وایم چې دې غریبې کونډې د نورو ټولو څخه زیاتې پیسې واچولې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_3.mp3', '', 1761754199, 1761754199),
(36081, 'Luke 21:4', 'Luke', 21, 4, 'ځکه چې هغوی ټولو هغه پیسې واچولې چې د هغوی د اړتیاوو څخه زیاتې وې، خو دې ښځې د خپلې غریبۍ سره بیاهم هرڅه چې یې لرل واچول.» د خدای د کور د ورانېدلو پېشګویي (متي ۲۴‏:‌۱‌‏-‌۲ او مرقوس ۱۳‏:‌۱‌‏-‌۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_4.mp3', '', 1761754199, 1761754199),
(36082, 'Luke 21:5', 'Luke', 21, 5, 'ځینو شاګردانو د خدای د کور په هکله خبرې کولې او د هغو ښکلو تیږو او نذرانو صفتونه یې کول چې د خدای کور ورباندې ښکلی شوی ؤ. عیسی وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_5.mp3', '', 1761754199, 1761754199),
(36083, 'Luke 21:6', 'Luke', 21, 6, '«دا شیان چې تاسو یې وینئ، داسې وخت به راشي چې په دې کې به یوه تیږه هم په بله تیږه پاتې نه شي او ټولې به راونړیږي.» د اخرې زمانې نښې (متي ۲۴‏:‌۳‌‏-‌۱۴ او مرقوس ۱۳‏:‌۳‌‏-‌۱۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_6.mp3', '', 1761754199, 1761754199),
(36084, 'Luke 21:7', 'Luke', 21, 7, 'هغوی پوښتنه وکړه: «ای استاذه! دا هرڅه به کله پېښیږي او د دې پېښو د رانژدې کېدلو نښې به څه وي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_7.mp3', '', 1761754199, 1761754199),
(36085, 'Luke 21:8', 'Luke', 21, 8, 'عیسی وویل: «پام کوئ چې بې‌لارې نه شئ. ځکه چې ډېر به زما په نوم راشي او وایي به: ‹زه مسیح یم› او ‹هغه وخت رارسېدلی دی‎.› خو د هغوی پسې مه ځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_8.mp3', '', 1761754199, 1761754199),
(36086, 'Luke 21:9', 'Luke', 21, 9, 'کله چې د جنګونو او ګډوډیو په هکله کوم څه اورئ، نو مه وېرېږئ. ځکه چې لومړی به دا شیان خامخا پېښیږي، خو دا د دې معنی نه لري چې دا هرڅه به سمدلاسه پای ته ورسیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_9.mp3', '', 1761754199, 1761754199),
(36087, 'Luke 21:10', 'Luke', 21, 10, 'بیا یې هغوی ته وویل: «یو قوم به د بل قوم سره جنګیږي، یوه پاچاهي به د بلې پاچاهۍ سره جنګیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_10.mp3', '', 1761754199, 1761754199),
(36088, 'Luke 21:11', 'Luke', 21, 11, 'سختې زلزلې به وشي، په ډېرو ځایونو کې به قحطي او وباګانې راشي او په اسمان کې به وېروونکې او لویې نښې راښکاره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_11.mp3', '', 1761754199, 1761754199),
(36089, 'Luke 21:12', 'Luke', 21, 12, 'خو له دې هرڅه نه مخکې به هغوی تاسو ونیسي او وبه مو ځوروي. تاسو به د محاکمې دپاره کنیسو ته وسپارل شئ او په زندانونو کې به واچول شئ او زما د نوم په خاطر به د محاکمې دپاره پاچاهانو او والیانو ته بوتلل شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_12.mp3', '', 1761754199, 1761754199),
(36090, 'Luke 21:13', 'Luke', 21, 13, 'دا به ستاسو دپاره د شاهدۍ ورکولو یوه موقعه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_13.mp3', '', 1761754199, 1761754199),
(36091, 'Luke 21:14', 'Luke', 21, 14, 'په دې هکله ډېر فکر مه کوئ چې د خپلو ځانونو څخه به څنګه دفاع کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_14.mp3', '', 1761754199, 1761754199),
(36092, 'Luke 21:15', 'Luke', 21, 15, 'ځکه چې زه به تاسو ته د خبرو کولو حکمت درکړم چې ستاسو له دښمنانو څخه به هېڅوک ونه شي کولای ستاسو په وړاندې ودریږي او یا مخالفت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_15.mp3', '', 1761754199, 1761754199),
(36093, 'Luke 21:16', 'Luke', 21, 16, 'تر دې چې ستاسو مور او پلار، ورونه، خپلوان او ملګري به ستاسو سره خیانت وکړي او ستاسو څخه به ځینې ووژل شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_16.mp3', '', 1761754199, 1761754199),
(36094, 'Luke 21:17', 'Luke', 21, 17, 'او زما د نوم له امله به ټول خلک ستاسو څخه کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_17.mp3', '', 1761754199, 1761754199),
(36095, 'Luke 21:18', 'Luke', 21, 18, 'خو ستاسو د سر یو ویښته به هم کم نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_18.mp3', '', 1761754199, 1761754199),
(36096, 'Luke 21:19', 'Luke', 21, 19, 'ټینګ ودرېږئ، نو تلپاتې ژوندون به وګټئ. د اورشلیم د ورانېدلو پېشګويي (متي ۲۴‏:‌۱۵‌‏-‌۲۱ او مرقوس ۱۳‏:‌۱۴‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_19.mp3', '', 1761754199, 1761754199),
(36097, 'Luke 21:20', 'Luke', 21, 20, 'خو کله چې تاسو ووینئ چې اورشلیم د لښکرو له خوا کلابند شوی دی، نو بیا پوه شئ چې د هغه د ورانېدلو وخت رانژدې شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_20.mp3', '', 1761754199, 1761754199),
(36098, 'Luke 21:21', 'Luke', 21, 21, 'نو په هغه وخت کې چې څوک په یهودیه کې وي هغه دې غرونو ته وتښتي. څوک چې په ښار کې وي، نو د ښار څخه دې ووځي او څوک چې د ښار څخه دباندې وي هغوی دې ښار ته نه ننوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_21.mp3', '', 1761754199, 1761754199),
(36099, 'Luke 21:22', 'Luke', 21, 22, 'ځکه چې دا به د سزا ورکولو ورځې وي، ترڅو هغه څه چې د خدای په کلام کې لیکل شوي دي پوره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_22.mp3', '', 1761754199, 1761754199),
(36100, 'Luke 21:23', 'Luke', 21, 23, 'افسوس دې وي د هغو ښځو په حال چې په هغو ورځو کې امیدوارې وي او په هغو میندو باندې چې خپلو ماشومانو ته شیدې ورکوي. ځکه چې د ځمکې په مخ به سخت مصیبت راشي او په دې خلکو به د خدای غضب نازل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_23.mp3', '', 1761754199, 1761754199),
(36101, 'Luke 21:24', 'Luke', 21, 24, 'هغوی به په تورو ووژل شي او ټولو هېوادونو ته به د اسیرانو په توګه بوتلل شي او اورشلیم به د غیریهودیانو له خوا تر‌پښو لاندې کیږي، ترڅو د غیریهودیانو دوران پای ته ونه رسیږي. د انسان د زوی راتګ (متي ۲۴‏:‌۲۹‌‏-‌۳۱ او مرقوس ۱۳‏:‌۲۴‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_24.mp3', '', 1761754199, 1761754199),
(36102, 'Luke 21:25', 'Luke', 21, 25, 'په لمر، سپوږمۍ او ستورو کې به نښې راښکاره شي او قومونه به د ځمکې په مخ د بحیرو د شور او څپو څخه تنګ او پرېشانه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_25.mp3', '', 1761754199, 1761754199),
(36103, 'Luke 21:26', 'Luke', 21, 26, 'خلک به د دې پېښې له وېرې او اندېښنې څخه چې په نړۍ کې رامنځته کیږي بې‌هوشه شي، ځکه چې اسماني موجودات به ولړزول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_26.mp3', '', 1761754199, 1761754199),
(36104, 'Luke 21:27', 'Luke', 21, 27, 'بیا به هغوی د انسان زوی وویني چې په ورېځ کې به د قدرت او زیات جلال سره راروان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_27.mp3', '', 1761754199, 1761754199),
(36105, 'Luke 21:28', 'Luke', 21, 28, 'کله چې دا شیان پیل شي نو تاسو نېغ ودرېږئ او زړور اوسئ، ځکه چې ستاسو خلاصون نژدې دی.» د انځر د ونې څخه عبرت اخیستل (متي ۲۴‏:‌۳۲‌‏-‌۳۵ او مرقوس ۱۳‏:‌۲۸‌‏-‌۳۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_28.mp3', '', 1761754199, 1761754199),
(36106, 'Luke 21:29', 'Luke', 21, 29, 'بیا عیسی هغوی ته دا مثال راوړ: «د انځر ونې او نورو ونو ته وګورئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_29.mp3', '', 1761754199, 1761754199),
(36107, 'Luke 21:30', 'Luke', 21, 30, 'کله چې هغه غوټۍ وسپړي، نو تاسو خپله وینئ او پوهېږئ چې اوړی رانژدې شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_30.mp3', '', 1761754199, 1761754199),
(36108, 'Luke 21:31', 'Luke', 21, 31, 'په همدې ډول کله چې د دې شیانو پېښېدل ووینئ، نو پوه شئ چې د خدای پاچاهي نژدې شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_31.mp3', '', 1761754199, 1761754199),
(36109, 'Luke 21:32', 'Luke', 21, 32, 'په یقین سره زه تاسو ته دا وایم چې دا نسل به تر هغې پورې له منځه لاړ نه شي، ترڅو دا ټولې پېښې رامنځته شوې نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_32.mp3', '', 1761754199, 1761754199),
(36110, 'Luke 21:33', 'Luke', 21, 33, 'ځمکه او اسمان به له منځه لاړ شي، خو زما خبرې به هېڅکله له منځه لاړې نه شي. بېداره اوسئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_33.mp3', '', 1761754199, 1761754199);